export type EventCallback = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, Set<EventCallback>> = new Map();

  publish(event: string, payload: any): void {
    const subs = this.subscribers.get(event);
    if (!subs) return;
    for (const cb of Array.from(subs)) {
      try {
        cb(payload);
      } catch (e) {
        // swallow subscriber errors to avoid breaking publisher
        // console.error('Event handler error', e);
      }
    }
  }

  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, new Set());
    }
    this.subscribers.get(event)!.add(callback);
  }
}

export type User = { id: string; name: string; email: string };

export class UserService {
  private store: Map<string, User> = new Map();

  create(user: User) {
    if (this.store.has(user.id)) throw new Error('User exists');
    this.store.set(user.id, user);
    return user;
  }

  getById(id: string) {
    return this.store.get(id) ?? null;
  }

  getAll() {
    return Array.from(this.store.values());
  }

  update(id: string, patch: Partial<User>) {
    const existing = this.store.get(id);
    if (!existing) return null;
    const updated = { ...existing, ...patch, id };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string) {
    return this.store.delete(id);
  }
}

export type Project = { id: string; name: string; description?: string; memberIds: string[] };

export class ProjectService {
  private store: Map<string, Project> = new Map();

  create(project: Project) {
    if (this.store.has(project.id)) throw new Error('Project exists');
    this.store.set(project.id, project);
    return project;
  }

  getById(id: string) {
    return this.store.get(id) ?? null;
  }

  getAll() {
    return Array.from(this.store.values());
  }

  update(id: string, patch: Partial<Project>) {
    const existing = this.store.get(id);
    if (!existing) return null;
    const updated = { ...existing, ...patch, id };
    // ensure memberIds exists
    if (!updated.memberIds) updated.memberIds = existing.memberIds || [];
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string) {
    return this.store.delete(id);
  }

  addMember(projectId: string, userId: string) {
    const p = this.store.get(projectId);
    if (!p) return null;
    if (!p.memberIds.includes(userId)) p.memberIds.push(userId);
    return p;
  }

  removeMember(projectId: string, userId: string) {
    const p = this.store.get(projectId);
    if (!p) return null;
    p.memberIds = p.memberIds.filter((id) => id !== userId);
    return p;
  }
}

import { EventBus } from "../event-bus";

export type TaskStatus = "todo" | "in-progress" | "done";
export type Task = { id: string; title: string; description?: string; status: TaskStatus; assigneeId?: string | null; projectId: string };

export class TaskService {
  private store: Map<string, Task> = new Map();
  private bus: EventBus;

  constructor(bus: EventBus) {
    this.bus = bus;
  }

  create(task: Task) {
    if (this.store.has(task.id)) throw new Error('Task exists');
    this.store.set(task.id, task);
    return task;
  }

  getById(id: string) {
    return this.store.get(id) ?? null;
  }

  getAll() {
    return Array.from(this.store.values());
  }

  update(id: string, patch: Partial<Task>) {
    const existing = this.store.get(id);
    if (!existing) return null;
    const updated = { ...existing, ...patch, id } as Task;
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string) {
    return this.store.delete(id);
  }

  assign(taskId: string, assigneeId: string) {
    const t = this.store.get(taskId);
    if (!t) return null;
    t.assigneeId = assigneeId;
    this.store.set(taskId, t);
    // publish event
    this.bus.publish('task.assigned', { taskId: t.id, taskTitle: t.title, assigneeId });
    return t;
  }

  changeStatus(taskId: string, newStatus: TaskStatus) {
    const t = this.store.get(taskId);
    if (!t) return null;
    const order = ["todo", "in-progress", "done"]; 
    const oldIndex = order.indexOf(t.status);
    const newIndex = order.indexOf(newStatus);
    if (newIndex === -1) throw new Error('Invalid status');
    if (newIndex < oldIndex) throw new Error('Cannot transition backwards');
    if (newIndex === oldIndex) return t;
    const oldStatus = t.status;
    t.status = newStatus;
    this.store.set(taskId, t);
    this.bus.publish('task.statusChanged', { taskId: t.id, taskTitle: t.title, assigneeId: t.assigneeId, oldStatus, newStatus });
    return t;
  }

  getByProject(projectId: string) {
    return Array.from(this.store.values()).filter((t) => t.projectId === projectId);
  }
}

